package org.example;

import org.json.JSONArray;
import org.json.JSONObject;
import java.sql.*;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.*;

/** Учёт жизненного цикла приборов: склад, партии поверки, позиции и групповые операции. */
public final class WorkflowDb {
    private WorkflowDb() {}

    public static void init() throws SQLException {
        try (Connection c=Db.openConnection(); Statement s=c.createStatement()) {
            s.execute("PRAGMA foreign_keys=ON");
            s.execute("CREATE TABLE IF NOT EXISTS kip_groups (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE COLLATE NOCASE, created_at TEXT NOT NULL DEFAULT (datetime('now')))");
            s.execute("CREATE TABLE IF NOT EXISTS kip_positions (id INTEGER PRIMARY KEY AUTOINCREMENT, group_id INTEGER NOT NULL, name TEXT NOT NULL, code TEXT, capacity INTEGER NOT NULL DEFAULT 0 CHECK(capacity>=0), compatible_type TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(group_id,name), FOREIGN KEY(group_id) REFERENCES kip_groups(id))");
            s.execute("CREATE TABLE IF NOT EXISTS device_workflow (device_id INTEGER PRIMARY KEY, status TEXT NOT NULL DEFAULT 'INSTALLED', position_id INTEGER, updated_at TEXT NOT NULL DEFAULT (datetime('now')), FOREIGN KEY(device_id) REFERENCES devices(id), FOREIGN KEY(position_id) REFERENCES kip_positions(id))");
            s.execute("CREATE TABLE IF NOT EXISTS verification_batches (id INTEGER PRIMARY KEY AUTOINCREMENT, batch_number TEXT NOT NULL UNIQUE, sent_date TEXT NOT NULL, provider TEXT, document_number TEXT, note TEXT, status TEXT NOT NULL DEFAULT 'IN_PROGRESS', created_by TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')))");
            s.execute("CREATE TABLE IF NOT EXISTS verification_batch_devices (batch_id INTEGER NOT NULL, device_id INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'SENT', returned_at TEXT, decision TEXT, PRIMARY KEY(batch_id,device_id), FOREIGN KEY(batch_id) REFERENCES verification_batches(id), FOREIGN KEY(device_id) REFERENCES devices(id))");
            s.execute("CREATE INDEX IF NOT EXISTS idx_workflow_status ON device_workflow(status)");
            // Существующие приборы не теряются: наличие старой позиции трактуем как эксплуатацию.
            s.execute("INSERT OR IGNORE INTO device_workflow(device_id,status) SELECT id, CASE WHEN COALESCE(TRIM(location),'')='' THEN 'WAREHOUSE' ELSE 'INSTALLED' END FROM devices WHERE is_deleted=0");
            seedLegacyPositions(c);
        }
    }

    /** Переносит уже заполненные поля «Группа / Наименование позиции» в новые справочники. */
    private record LegacyDevice(long id,String location,String details) {}
    private static void seedLegacyPositions(Connection c) throws SQLException {
        List<LegacyDevice> legacy=new ArrayList<>();
        try(PreparedStatement ps=c.prepareStatement("SELECT id,location,details_json FROM devices WHERE is_deleted=0");ResultSet r=ps.executeQuery()) {
            while(r.next()) legacy.add(new LegacyDevice(r.getLong("id"),r.getString("location"),r.getString("details_json")));
        }
        for(LegacyDevice item:legacy) {
            long deviceId=item.id(); JSONObject d;
            try { d=new JSONObject(n(item.details())); } catch(Exception e) { continue; }
            String group=n(d.optString("groupName","")), position=n(d.optString("positionName",""));
            if(!n(d.optString("writeOff","")).isBlank()) { updateStatus(c,deviceId,"WRITTEN_OFF",null); clearPosition(c,deviceId); }
            if(group.isBlank()||position.isBlank()) continue;
            long groupId;
            try(PreparedStatement q=c.prepareStatement("INSERT OR IGNORE INTO kip_groups(name) VALUES(?)")){q.setString(1,group);q.executeUpdate();}
            try(PreparedStatement q=c.prepareStatement("SELECT id FROM kip_groups WHERE name=? COLLATE NOCASE")){q.setString(1,group);try(ResultSet g=q.executeQuery()){if(!g.next())continue;groupId=g.getLong(1);}}
            String code=n(item.location());
            try(PreparedStatement q=c.prepareStatement("INSERT OR IGNORE INTO kip_positions(group_id,name,code,capacity) VALUES(?,?,?,0)")){q.setLong(1,groupId);q.setString(2,position);q.setString(3,code);q.executeUpdate();}
            try(PreparedStatement q=c.prepareStatement("SELECT id FROM kip_positions WHERE group_id=? AND name=? COLLATE NOCASE")){q.setLong(1,groupId);q.setString(2,position);try(ResultSet p=q.executeQuery()){if(p.next()){try(PreparedStatement u=c.prepareStatement("UPDATE device_workflow SET position_id=? WHERE device_id=? AND status='INSTALLED' AND position_id IS NULL")){u.setLong(1,p.getLong(1));u.setLong(2,deviceId);u.executeUpdate();}}}}
        }
    }

    public static JSONArray listDevices(String status) throws SQLException {
        JSONArray a=new JSONArray();
        String sql="SELECT d.id,d.serial_number,d.name,d.location,w.status,w.position_id,p.name AS position_name,g.name AS group_name, d.details_json FROM devices d JOIN device_workflow w ON w.device_id=d.id LEFT JOIN kip_positions p ON p.id=w.position_id LEFT JOIN kip_groups g ON g.id=p.group_id WHERE d.is_deleted=0"+(status==null||status.isBlank()?"":" AND w.status=?")+" ORDER BY d.name,d.serial_number";
        try(Connection c=Db.openConnection()){
            try(Statement st=c.createStatement()){st.executeUpdate("INSERT OR IGNORE INTO device_workflow(device_id,status) SELECT id,CASE WHEN COALESCE(TRIM(location),'')='' THEN 'WAREHOUSE' ELSE 'INSTALLED' END FROM devices WHERE is_deleted=0");}
            try(PreparedStatement ps=c.prepareStatement(sql)){if(status!=null&&!status.isBlank())ps.setString(1,status);try(ResultSet r=ps.executeQuery()){while(r.next()){JSONObject x=new JSONObject().put("id",r.getLong("id")).put("serialNumber",n(r.getString("serial_number"))).put("name",n(r.getString("name"))).put("legacyLocation",n(r.getString("location"))).put("status",r.getString("status")).put("positionId",r.getObject("position_id")==null?JSONObject.NULL:r.getLong("position_id")).put("positionName",n(r.getString("position_name"))).put("groupName",n(r.getString("group_name")));a.put(x);}}}
        }
        return a;
    }
    public static JSONArray groups() throws SQLException { JSONArray a=new JSONArray();try(Connection c=Db.openConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id,name FROM kip_groups ORDER BY name")){while(r.next())a.put(new JSONObject().put("id",r.getLong(1)).put("name",r.getString(2)));}return a; }
    public static long addGroup(String name) throws SQLException {try(Connection c=Db.openConnection();PreparedStatement p=c.prepareStatement("INSERT INTO kip_groups(name) VALUES(?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,required(name,"Название группы"));p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){return r.next()?r.getLong(1):lastId(c);}}}
    public static JSONArray positions() throws SQLException {JSONArray a=new JSONArray();String q="SELECT p.id,p.name,p.code,p.capacity,p.compatible_type,g.id group_id,g.name group_name,(SELECT COUNT(*) FROM device_workflow w WHERE w.position_id=p.id AND w.status='INSTALLED') occupied FROM kip_positions p JOIN kip_groups g ON g.id=p.group_id ORDER BY g.name,p.name";try(Connection c=Db.openConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(q)){while(r.next())a.put(new JSONObject().put("id",r.getLong("id")).put("name",r.getString("name")).put("code",n(r.getString("code"))).put("capacity",r.getInt("capacity")).put("compatibleType",n(r.getString("compatible_type"))).put("groupId",r.getLong("group_id")).put("groupName",r.getString("group_name")).put("occupied",r.getInt("occupied")));}return a;}
    public static long addPosition(long groupId,String name,String code,int capacity,String compatible) throws SQLException {if(capacity<0)throw new IllegalArgumentException("Вместимость не может быть отрицательной");try(Connection c=Db.openConnection();PreparedStatement p=c.prepareStatement("INSERT INTO kip_positions(group_id,name,code,capacity,compatible_type) VALUES(?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setLong(1,groupId);p.setString(2,required(name,"Название позиции"));p.setString(3,n(code));p.setInt(4,capacity);p.setString(5,n(compatible));p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){return r.next()?r.getLong(1):lastId(c);}}}

    public static void moveToWarehouse(JSONArray ids,String user) throws SQLException {if(ids.length()==0)throw new IllegalArgumentException("Не выбраны приборы");try(Connection c=Db.openConnection()){c.setAutoCommit(false);try{for(int i=0;i<ids.length();i++){long id=ids.getLong(i);String old=status(c,id);if(!"INSTALLED".equals(old))throw new IllegalStateException("Прибор #"+id+" нельзя снять: текущее состояние "+old);String from=currentLocation(c,id);updateStatus(c,id,"WAREHOUSE",null);clearPosition(c,id);logMove(c,id,"Снят с позиции",from,"Склад КИП",user);}c.commit();}catch(SQLException|RuntimeException e){c.rollback();throw e;}}}
    public static long createBatch(JSONArray ids,String date,String provider,String doc,String note,String user) throws SQLException {if(ids.length()==0)throw new IllegalArgumentException("Не выбраны приборы");if(date==null||!date.matches("\\d{4}-\\d{2}-\\d{2}"))throw new IllegalArgumentException("Некорректная дата отправки");try(Connection c=Db.openConnection()){c.setAutoCommit(false);try{String number="ПВ-"+LocalDate.now().getYear()+"-"+String.format("%04d",nextBatch(c));long bid;try(PreparedStatement p=c.prepareStatement("INSERT INTO verification_batches(batch_number,sent_date,provider,document_number,note,created_by) VALUES(?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,number);p.setString(2,date);p.setString(3,n(provider));p.setString(4,n(doc));p.setString(5,n(note));p.setString(6,n(user));p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();bid=r.getLong(1);}}for(int i=0;i<ids.length();i++){long id=ids.getLong(i);if(!"WAREHOUSE".equals(status(c,id)))throw new IllegalStateException("Прибор #"+id+" не находится на складе КИП");try(PreparedStatement p=c.prepareStatement("INSERT INTO verification_batch_devices(batch_id,device_id) VALUES(?,?)")){p.setLong(1,bid);p.setLong(2,id);p.executeUpdate();}updateStatus(c,id,"VERIFICATION",null);logMove(c,id,"Отправлен на поверку","Склад КИП",number,user);}c.commit();return bid;}catch(SQLException|RuntimeException e){c.rollback();throw e;}}}
    public static JSONArray batches() throws SQLException {JSONArray a=new JSONArray();String q="SELECT b.*,COUNT(bd.device_id) total,SUM(CASE WHEN bd.status='SENT' THEN 1 ELSE 0 END) pending,SUM(CASE WHEN bd.status<>'SENT' THEN 1 ELSE 0 END) completed FROM verification_batches b LEFT JOIN verification_batch_devices bd ON bd.batch_id=b.id GROUP BY b.id ORDER BY b.id DESC";try(Connection c=Db.openConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery(q)){while(r.next())a.put(new JSONObject().put("id",r.getLong("id")).put("batchNumber",r.getString("batch_number")).put("sentDate",r.getString("sent_date")).put("provider",n(r.getString("provider"))).put("documentNumber",n(r.getString("document_number"))).put("status",r.getString("status")).put("total",r.getInt("total")).put("pending",r.getInt("pending")).put("completed",r.getInt("completed")));}return a;}
    public static JSONArray batchDevices(long batchId) throws SQLException {JSONArray a=new JSONArray();String q="SELECT d.id,d.name,d.serial_number,bd.status,bd.decision FROM verification_batch_devices bd JOIN devices d ON d.id=bd.device_id WHERE bd.batch_id=? ORDER BY d.name";try(Connection c=Db.openConnection();PreparedStatement p=c.prepareStatement(q)){p.setLong(1,batchId);try(ResultSet r=p.executeQuery()){while(r.next())a.put(new JSONObject().put("id",r.getLong("id")).put("name",r.getString("name")).put("serialNumber",n(r.getString("serial_number"))).put("status",r.getString("status")).put("decision",n(r.getString("decision"))));}}return a;}
    public static void receive(long batchId,JSONArray ids,String decision,String user) throws SQLException {if(ids.length()==0)throw new IllegalArgumentException("Не выбраны возвращаемые приборы");if(!Set.of("WAREHOUSE","WRITTEN_OFF").contains(decision))throw new IllegalArgumentException("Неизвестное решение");try(Connection c=Db.openConnection()){c.setAutoCommit(false);try{for(int i=0;i<ids.length();i++){long id=ids.getLong(i);try(PreparedStatement p=c.prepareStatement("UPDATE verification_batch_devices SET status='RETURNED',returned_at=?,decision=? WHERE batch_id=? AND device_id=? AND status='SENT'")){p.setString(1,LocalDateTime.now().toString());p.setString(2,decision);p.setLong(3,batchId);p.setLong(4,id);if(p.executeUpdate()!=1)throw new IllegalStateException("Прибор #"+id+" не числится ожидающим возврата в этой партии");}updateStatus(c,id,decision,null);clearPosition(c,id);logMove(c,id,"Возвращён с поверки","Поверка",decision.equals("WAREHOUSE")?"Склад КИП":"Списан",user);}try(PreparedStatement p=c.prepareStatement("UPDATE verification_batches SET status=CASE WHEN EXISTS(SELECT 1 FROM verification_batch_devices WHERE batch_id=? AND status='SENT') THEN 'IN_PROGRESS' ELSE 'COMPLETED' END WHERE id=?")){p.setLong(1,batchId);p.setLong(2,batchId);p.executeUpdate();}c.commit();}catch(SQLException|RuntimeException e){c.rollback();throw e;}}}
    public static void writeOff(JSONArray ids,String reason,String user) throws SQLException {if(ids.length()==0)throw new IllegalArgumentException("Не выбраны приборы");try(Connection c=Db.openConnection()){c.setAutoCommit(false);try{for(int i=0;i<ids.length();i++){long id=ids.getLong(i);String st=status(c,id);if("WRITTEN_OFF".equals(st))throw new IllegalStateException("Прибор #"+id+" уже списан");String from=currentLocation(c,id);if(from.isBlank())from=st;updateStatus(c,id,"WRITTEN_OFF",null);clearPosition(c,id);try(PreparedStatement p=c.prepareStatement("UPDATE verification_batch_devices SET status='WRITTEN_OFF',decision='WRITTEN_OFF',returned_at=? WHERE device_id=? AND status='SENT'")){p.setString(1,LocalDateTime.now().toString());p.setLong(2,id);p.executeUpdate();}logMove(c,id,"Списан",from,"Списан"+(n(reason).isBlank()?"":" — "+n(reason)),user);}try(PreparedStatement p=c.prepareStatement("UPDATE verification_batches SET status=CASE WHEN EXISTS(SELECT 1 FROM verification_batch_devices bd WHERE bd.batch_id=verification_batches.id AND bd.status='SENT') THEN 'IN_PROGRESS' ELSE 'COMPLETED' END")){p.executeUpdate();}c.commit();}catch(SQLException|RuntimeException e){c.rollback();throw e;}}}
    public static void install(JSONArray assignments,String user) throws SQLException {if(assignments.length()==0)throw new IllegalArgumentException("Нет назначений");try(Connection c=Db.openConnection()){c.setAutoCommit(false);try{Map<Long,Integer> add=new HashMap<>();for(int i=0;i<assignments.length();i++){JSONObject a=assignments.getJSONObject(i);long id=a.getLong("deviceId"),pid=a.getLong("positionId");if(!"WAREHOUSE".equals(status(c,id)))throw new IllegalStateException("Прибор #"+id+" должен находиться на складе КИП");String compatible="";try(PreparedStatement p=c.prepareStatement("SELECT compatible_type FROM kip_positions WHERE id=?")){p.setLong(1,pid);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Позиция не найдена: "+pid);compatible=n(r.getString(1));}}if(!compatible.isBlank()){String sensor="";try(PreparedStatement p=c.prepareStatement("SELECT details_json FROM devices WHERE id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){if(r.next())try{sensor=new JSONObject(r.getString(1)).optString("sensorType","").trim();}catch(Exception ignored){}}}if(!compatible.equalsIgnoreCase(sensor))throw new IllegalStateException("Прибор #"+id+" несовместим с выбранной позицией: требуется тип «"+compatible+"»");}add.merge(pid,1,Integer::sum);}for(var e:add.entrySet()){try(PreparedStatement p=c.prepareStatement("SELECT capacity,(SELECT COUNT(*) FROM device_workflow WHERE position_id=? AND status='INSTALLED') occupied FROM kip_positions WHERE id=?")){p.setLong(1,e.getKey());p.setLong(2,e.getKey());try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Позиция не найдена: "+e.getKey());int cap=r.getInt("capacity"),used=r.getInt("occupied");if(cap>0&&used+e.getValue()>cap)throw new IllegalStateException("Недостаточно мест на позиции #"+e.getKey()+": свободно "+Math.max(0,cap-used));}}}for(int i=0;i<assignments.length();i++){JSONObject a=assignments.getJSONObject(i);long id=a.getLong("deviceId"),pid=a.getLong("positionId");updateStatus(c,id,"INSTALLED",pid);String place;try(PreparedStatement p=c.prepareStatement("SELECT g.name||' / '||p.name FROM kip_positions p JOIN kip_groups g ON g.id=p.group_id WHERE p.id=?")){p.setLong(1,pid);try(ResultSet r=p.executeQuery()){r.next();place=r.getString(1);}}String groupName="",positionName="";try(PreparedStatement p=c.prepareStatement("SELECT g.name,p.name FROM kip_positions p JOIN kip_groups g ON g.id=p.group_id WHERE p.id=?")){p.setLong(1,pid);try(ResultSet r=p.executeQuery()){r.next();groupName=r.getString(1);positionName=r.getString(2);}}try(PreparedStatement p=c.prepareStatement("SELECT details_json FROM devices WHERE id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){r.next();JSONObject details;try{details=new JSONObject(r.getString(1));}catch(Exception ignored){details=new JSONObject();}details.put("groupName",groupName).put("positionName",positionName);try(PreparedStatement u=c.prepareStatement("UPDATE devices SET location=?,details_json=?,version=version+1 WHERE id=?")){u.setString(1,place);u.setString(2,details.toString());u.setLong(3,id);u.executeUpdate();}}}logMove(c,id,"Установлен на позицию","Склад КИП",place,user);}c.commit();}catch(SQLException|RuntimeException e){c.rollback();throw e;}}}

    public static String deviceStatus(long id) throws SQLException {try(Connection c=Db.openConnection();PreparedStatement p=c.prepareStatement("SELECT status FROM device_workflow WHERE device_id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next()?r.getString(1):"";}}}
    private static void clearPosition(Connection c,long id)throws SQLException{try(PreparedStatement p=c.prepareStatement("UPDATE devices SET location=NULL,version=version+1 WHERE id=?")){p.setLong(1,id);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("SELECT details_json FROM devices WHERE id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){if(r.next()){JSONObject d;try{d=new JSONObject(r.getString(1));}catch(Exception e){d=new JSONObject();}d.put("groupName","").put("positionName","");try(PreparedStatement u=c.prepareStatement("UPDATE devices SET details_json=? WHERE id=?")){u.setString(1,d.toString());u.setLong(2,id);u.executeUpdate();}}}}}
    private static String status(Connection c,long id)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT w.status FROM device_workflow w JOIN devices d ON d.id=w.device_id WHERE w.device_id=? AND d.is_deleted=0")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Прибор не найден: "+id);return r.getString(1);}}}
    private static void updateStatus(Connection c,long id,String status,Long pos)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO device_workflow(device_id,status,position_id,updated_at) VALUES(?,?,?,datetime('now')) ON CONFLICT(device_id) DO UPDATE SET status=excluded.status,position_id=excluded.position_id,updated_at=excluded.updated_at")){p.setLong(1,id);p.setString(2,status);if(pos==null)p.setNull(3,Types.INTEGER);else p.setLong(3,pos);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("UPDATE devices SET version=version+1 WHERE id=?")){p.setLong(1,id);p.executeUpdate();}}
    private static String currentLocation(Connection c,long id)throws SQLException{try(PreparedStatement p=c.prepareStatement("SELECT location FROM devices WHERE id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next()?n(r.getString(1)):"";}}}
    private static void log(Connection c,long id,String action,String details,String user)throws SQLException{logMove(c,id,action,"",details,user);}
    private static void logMove(Connection c,long id,String action,String from,String to,String user)throws SQLException{String details=(n(from).isBlank()?"":n(from)+" → ")+n(to);try(PreparedStatement p=c.prepareStatement("INSERT INTO audit_log(device_id,changed_at,changed_by,action,details) VALUES(?,datetime('now'),?,?,?)")){p.setLong(1,id);p.setString(2,n(user));p.setString(3,action);p.setString(4,details);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("INSERT INTO device_movements(device_id,event_date,event_type,from_place,to_place,note,created_by,created_at) VALUES(?,?,?,?,?,?,?,datetime('now'))")){p.setLong(1,id);p.setString(2,LocalDate.now().toString());p.setString(3,action);p.setString(4,n(from));p.setString(5,n(to));p.setString(6,details);p.setString(7,n(user));p.executeUpdate();}}
    private static int nextBatch(Connection c)throws SQLException{try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*)+1 FROM verification_batches WHERE sent_date LIKE '"+LocalDate.now().getYear()+"-%'")){return r.next()?r.getInt(1):1;}}
    private static long lastId(Connection c)throws SQLException{try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT last_insert_rowid()")){r.next();return r.getLong(1);}}
    private static String required(String s,String field){if(s==null||s.isBlank())throw new IllegalArgumentException(field+" обязательно");return s.trim();}
    private static String n(String s){return s==null?"":s.trim();}
}